+using Microsoft.EntityFrameworkCore;
+using ShipmentTracker.Client.Models;
+using ShipmentTracker.Client.Services;
+using ShipmentTracker.Data;
+
+namespace ShipmentTracker.Services;
+
+public class ServerShipmentService(ApplicationDbContext db) : IShipmentService
+{
+    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
+    {
+        return await db.Shipments
+            .OrderByDescending(s => s.CreatedAtUtc)
+            .Select(s => ToDto(s))
+            .ToListAsync();
+    }
+
+    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
+    {
+        var shipment = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
+        return shipment is null ? null : ToDto(shipment);
+    }
+
+    public async Task<List<ShipmentDto>> GetShipmentsForCustomerAsync(string email)
+    {
+        return await db.Shipments
+            .Where(s => s.CustomerEmail == email)
+            .OrderByDescending(s => s.CreatedAtUtc)
+            .Select(s => ToDto(s))
+            .ToListAsync();
+    }
+
+    public async Task<ShipmentDto> CreateShipmentAsync(CreateShipmentDto dto)
+    {
+        var shipment = new Shipment
+        {
+            TrackingNumber = GenerateTrackingNumber(),
+            Origin = dto.Origin,
+            Destination = dto.Destination,
+            CustomerEmail = dto.CustomerEmail,
+            Description = dto.Description,
+            WeightKg = dto.WeightKg,
+            EstimatedDeliveryUtc = dto.EstimatedDeliveryUtc,
+            Status = ShipmentStatuses.Pending,
+            CreatedAtUtc = DateTime.UtcNow
+        };
+
+        db.Shipments.Add(shipment);
+        await db.SaveChangesAsync();
+        return ToDto(shipment);
+    }
+
+    public async Task<ShipmentDto?> UpdateShipmentStatusAsync(int id, UpdateShipmentStatusDto dto)
+    {
+        var shipment = await db.Shipments.FindAsync(id);
+        if (shipment is null) return null;
+
+        shipment.Status = dto.Status;
+        if (dto.Status == ShipmentStatuses.Delivered)
+            shipment.ActualDeliveryUtc = DateTime.UtcNow;
+
+        await db.SaveChangesAsync();
+        return ToDto(shipment);
+    }
+
+    private static ShipmentDto ToDto(Shipment s) => new()
+    {
+        Id = s.Id,
+        TrackingNumber = s.TrackingNumber,
+        Origin = s.Origin,
+        Destination = s.Destination,
+        Status = s.Status,
+        CreatedAtUtc = s.CreatedAtUtc,
+        EstimatedDeliveryUtc = s.EstimatedDeliveryUtc,
+        ActualDeliveryUtc = s.ActualDeliveryUtc,
+        CustomerEmail = s.CustomerEmail,
+        Description = s.Description,
+        WeightKg = s.WeightKg
+    };
+
+    private static string GenerateTrackingNumber()
+    {
+        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(100000, 999999)}";
+    }
+}
+

