@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Track Shipment</PageTitle>

<h2>🔍 Track Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="Search" disabled="@(string.IsNullOrWhiteSpace(trackingNumber) || loading)">
                @if (loading) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Search
            </button>
        </div>
    </div>
</div>

@if (searched && shipment is null)
{
    <div class="alert alert-warning">No shipment found with tracking number "<strong>@searchedNumber</strong>".</div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">Tracking: @shipment.TrackingNumber</h5>
            <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <p><strong>Origin:</strong> @shipment.Origin</p>
                    <p><strong>Destination:</strong> @shipment.Destination</p>
                    <p><strong>Description:</strong> @shipment.Description</p>
                    @if (shipment.WeightKg.HasValue)
                    {
                        <p><strong>Weight:</strong> @shipment.WeightKg.Value.ToString("F1") kg</p>
                    }
                </div>
                <div class="col-md-6">
                    <p><strong>Created:</strong> @shipment.CreatedAtUtc.ToString("g")</p>
                    @if (shipment.EstimatedDeliveryUtc.HasValue)
                    {
                        <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDeliveryUtc.Value.ToString("g")</p>
                    }
                    @if (shipment.ActualDeliveryUtc.HasValue)
                    {
                        <p><strong>Delivered:</strong> @shipment.ActualDeliveryUtc.Value.ToString("g")</p>
                    }
                </div>
            </div>

            <hr />
            <h6>Status Timeline</h6>
            <div class="d-flex flex-wrap gap-2 mt-2">
                @foreach (var status in ShipmentStatuses.All)
                {
                    var reached = GetStatusIndex(shipment.Status) >= GetStatusIndex(status);
                    <div class="d-flex align-items-center">
                        <span class="badge @(reached ? "bg-success" : "bg-secondary") me-1">@(reached ? "✓" : "○")</span>
                        <span class="@(reached ? "fw-bold" : "text-muted")">@status</span>
                        @if (status != ShipmentStatuses.All.Last())
                        {
                            <span class="mx-2 text-muted">→</span>
                        }
                    </div>
                }
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromQuery(Name = "number")]
    public string? InitialTrackingNumber { get; set; }

    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private ShipmentDto? shipment;
    private bool loading;
    private bool searched;

    protected override async Task OnInitializedAsync()
    {
        if (!string.IsNullOrWhiteSpace(InitialTrackingNumber))
        {
            trackingNumber = InitialTrackingNumber;
            await Search();
        }
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        loading = true;
        searched = false;
        searchedNumber = trackingNumber.Trim();
        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        }
        catch
        {
            shipment = null;
        }
        searched = true;
        loading = false;
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") _ = Search();
    }

    private static int GetStatusIndex(string status) =>
        Array.IndexOf(ShipmentStatuses.All, status);

    private static string GetStatusBadgeClass(string status) => status switch
    {
        ShipmentStatuses.Delivered => "bg-success",
        ShipmentStatuses.Cancelled => "bg-danger",
        ShipmentStatuses.InTransit or ShipmentStatuses.OutForDelivery => "bg-info text-dark",
        _ => "bg-warning text-dark"
    };
}

@page "/shipments"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatch Board</PageTitle>

<div class="d-flex justify-content-between align-items-center mb-3">
    <h2>🚛 Dispatch Board</h2>
    <button class="btn btn-success" @onclick="() => showCreateForm = !showCreateForm">
        @(showCreateForm ? "Cancel" : "+ New Shipment")
    </button>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5>Create New Shipment</h5>
            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Origin</label>
                    <input class="form-control" @bind="newShipment.Origin" placeholder="e.g. New York, NY" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Destination</label>
                    <input class="form-control" @bind="newShipment.Destination" placeholder="e.g. Los Angeles, CA" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Customer Email</label>
                    <input class="form-control" type="email" @bind="newShipment.CustomerEmail" placeholder="customer@example.com" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Description</label>
                    <input class="form-control" @bind="newShipment.Description" placeholder="Package description" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Weight (kg)</label>
                    <input class="form-control" type="number" step="0.1" @bind="newShipment.WeightKg" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Est. Delivery</label>
                    <input class="form-control" type="date" @bind="newShipment.EstimatedDeliveryUtc" />
                </div>
                <div class="col-12">
                    <button class="btn btn-primary" @onclick="CreateShipment" disabled="@creating">
                        @if (creating) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Create Shipment
                    </button>
                </div>
            </div>
            @if (!string.IsNullOrEmpty(createError))
            {
                <div class="alert alert-danger mt-2">@createError</div>
            }
        </div>
    </div>
}

<div class="mb-3">
    <label class="form-label fw-bold">Filter by Status:</label>
    <select class="form-select w-auto d-inline-block ms-2" @bind="statusFilter">
        <option value="">All</option>
        @foreach (var s in ShipmentStatuses.All)
        {
            <option value="@s">@s</option>
        }
    </select>
    <button class="btn btn-sm btn-outline-secondary ms-2" @onclick="LoadShipments">🔄 Refresh</button>
</div>

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (filteredShipments.Count == 0)
{
    <div class="alert alert-info">No shipments found.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Customer</th>
                    <th>Created</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in filteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.CustomerEmail</td>
                        <td>@s.CreatedAtUtc.ToString("d")</td>
                        <td>
                            @if (editingId == s.Id)
                            {
                                <select class="form-select form-select-sm d-inline-block w-auto" @bind="editStatus">
                                    @foreach (var st in ShipmentStatuses.All)
                                    {
                                        <option value="@st">@st</option>
                                    }
                                </select>
                                <button class="btn btn-sm btn-primary ms-1" @onclick="() => SaveStatus(s.Id)">Save</button>
                                <button class="btn btn-sm btn-secondary ms-1" @onclick="() => editingId = null">Cancel</button>
                            }
                            else
                            {
                                <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(s)">Update Status</button>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentDto> allShipments = [];
    private List<ShipmentDto> filteredShipments = [];
    private string statusFilter = string.Empty;
    private bool loading = true;
    private bool showCreateForm;
    private bool creating;
    private string? createError;
    private CreateShipmentDto newShipment = new();
    private int? editingId;
    private string editStatus = string.Empty;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        try
        {
            allShipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch
        {
            allShipments = [];
        }
        ApplyFilter();
        loading = false;
    }

    private string StatusFilter
    {
        get => statusFilter;
        set { statusFilter = value; ApplyFilter(); }
    }

    private void ApplyFilter()
    {
        filteredShipments = string.IsNullOrEmpty(statusFilter)
            ? allShipments
            : allShipments.Where(s => s.Status == statusFilter).ToList();
    }

    private async Task CreateShipment()
    {
        creating = true;
        createError = null;
        try
        {
            await ShipmentService.CreateShipmentAsync(newShipment);
            newShipment = new();
            showCreateForm = false;
            await LoadShipments();
        }
        catch (Exception ex)
        {
            createError = $"Failed to create shipment: {ex.Message}";
        }
        creating = false;
    }

    private void StartEdit(ShipmentDto s)
    {
        editingId = s.Id;
        editStatus = s.Status;
    }

    private async Task SaveStatus(int id)
    {
        await ShipmentService.UpdateShipmentStatusAsync(id, new UpdateShipmentStatusDto { Status = editStatus });
        editingId = null;
        await LoadShipments();
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        ShipmentStatuses.Delivered => "bg-success",
        ShipmentStatuses.Cancelled => "bg-danger",
        ShipmentStatuses.InTransit or ShipmentStatuses.OutForDelivery => "bg-info text-dark",
        _ => "bg-warning text-dark"
    };
}

