22.                 <div class="col-md-6">
23.                     <label class="form-label">Origin</label>
24.                     <input class="form-control" @bind="newShipment.Origin" placeholder="e.g. New York, NY" />
25.                 </div>
26.                 <div class="col-md-6">
27.                     <label class="form-label">Destination</label>
