36.                     <input class="form-control" @bind="newShipment.Description" placeholder="Package description" />
37.                 </div>
38.                 <div class="col-md-3">
39.                     <label class="form-label">Weight (kg)</label>
40.                     <input class="form-control" type="number" step="0.1" @bind="newShipment.WeightKg" />
41.                 </div>
42.                 <div class="col-md-3">
43.                     <label class="form-label">Est. Delivery</label>
44.                     <input class="form-control" type="date" @bind="newShipment.EstimatedDeliveryUtc" />
45.                 </div>
46.                 <div class="col-12">
47.                     <button class="btn btn-primary" @onclick="CreateShipment" disabled="@creating">
48.                         @if (creating) { <span class="spinner-border spinner-border-sm me-1"></span> }
49.                         Create Shipment
50.                     </button>
51.                 </div>
52.             </div>
53.             @if (!string.IsNullOrEmpty(createError))
54.             {
55.                 <div class="alert alert-danger mt-2">@createError</div>
56.             }
57.         </div>
58.     </div>
59. }
60. 
61. <div class="mb-3">
62.     <label class="form-label fw-bold">Filter by Status:</label>
63.     <select class="form-select w-auto d-inline-block ms-2" @bind="statusFilter">
64.         <option value="">All</option>
65.         @foreach (var s in ShipmentStatuses.All)
66.         {
67.             <option value="@s">@s</option>
68.         }
69.     </select>
70.     <button class="btn btn-sm btn-outline-secondary ms-2" @onclick="LoadShipments">🔄 Refresh</button>
71. </div>
72. 
73. @if (loading)
74. {
75.     <p><em>Loading shipments...</em></p>
76. }
77. else if (filteredShipments.Count == 0)
78. {
79.     <div class="alert alert-info">No shipments found.</div>
80. }
81. else
82. {
83.     <div class="table-responsive">
84.         <table class="table table-striped table-hover">
85.             <thead class="table-dark">
86.                 <tr>
87.                     <th>Tracking #</th>
88.                     <th>Origin</th>
89.                     <th>Destination</th>
90.                     <th>Status</th>
91.                     <th>Customer</th>
92.                     <th>Created</th>
93.                     <th>Actions</th>
94.                 </tr>
95.             </thead>
96.             <tbody>
97.                 @foreach (var s in filteredShipments)
98.                 {
99.                     <tr>
100.                         <td><code>@s.TrackingNumber</code></td>
101.                         <td>@s.Origin</td>
102.                         <td>@s.Destination</td>
103.                         <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
104.                         <td>@s.CustomerEmail</td>
105.                         <td>@s.CreatedAtUtc.ToString("d")</td>
106.                         <td>
107.                             @if (editingId == s.Id)
108.                             {
109.                                 <select class="form-select form-select-sm d-inline-block w-auto" @bind="editStatus">
110.                                     @foreach (var st in ShipmentStatuses.All)
111.                                     {
