113.                                     }
114.                                 </select>
115.                                 <button class="btn btn-sm btn-primary ms-1" @onclick="() => SaveStatus(s.Id)">Save</button>
116.                                 <button class="btn btn-sm btn-secondary ms-1" @onclick="() => editingId = null">Cancel</button>
117.                             }
118.                             else
119.                             {
120.                                 <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(s)">Update Status</button>
121.                             }
122.                         </td>
123.                     </tr>
124.                 }
125.             </tbody>
126.         </table>
127.     </div>
