162.     private string StatusFilter
163.     {
164.         get => statusFilter;
165.         set { statusFilter = value; ApplyFilter(); }
166.     }
167. 
168.     private void ApplyFilter()
169.     {
170.         filteredShipments = string.IsNullOrEmpty(statusFilter)
171.             ? allShipments
172.             : allShipments.Where(s => s.Status == statusFilter).ToList();
173.     }
