4. @using Microsoft.AspNetCore.Components.Authorization
5. @attribute [Authorize(Roles = "Customer")]
6. @inject IShipmentService ShipmentService
7. @inject AuthenticationStateProvider AuthStateProvider
8. 
9. <PageTitle>My Shipments</PageTitle>
10. 
11. <h2>📋 My Shipments</h2>
12. 
13. <div class="mb-3">
14.     <button class="btn btn-sm btn-outline-secondary" @onclick="LoadShipments">🔄 Refresh</button>
15. </div>
16. 
17. @if (loading)
18. {
