44.                         {
45.                             <p class="text-success"><strong>Delivered:</strong> @s.ActualDeliveryUtc.Value.ToString("g")</p>
46.                         }
47.                     </div>
48.                 </div>
49.             </div>
50.         }
51.     </div>
52. }
