 @page "/my-shipments"
 @using ShipmentTracker.Client.Models
 @using ShipmentTracker.Client.Services
 @using Microsoft.AspNetCore.Components.Authorization
 @attribute [Authorize(Roles = "Customer")]
 @inject IShipmentService ShipmentService
 @inject AuthenticationStateProvider AuthStateProvider

 <PageTitle>My Shipments</PageTitle>

 <h2>📋 My Shipments</h2>

 <div class="mb-3">
     <button class="btn btn-sm btn-outline-secondary" @onclick="LoadShipments">🔄 Refresh</button>
 </div>

 @if (loading)
 {
     <p><em>Loading your shipments...</em></p>
 }
 else if (shipments.Count == 0)
 {
     <div class="alert alert-info">You don't have any shipments yet.</div>
 }
 else
 {
     <div class="row">
         @foreach (var s in shipments)
         {
             <div class="col-md-6 mb-3">
                 <div class="card">
                     <div class="card-header d-flex justify-content-between">
                         <code>@s.TrackingNumber</code>
                         <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
                     </div>
                     <div class="card-body">
                         <p><strong>From:</strong> @s.Origin → <strong>To:</strong> @s.Destination</p>
                         <p><strong>Description:</strong> @s.Description</p>
                         @if (s.EstimatedDeliveryUtc.HasValue)
                         {
                             <p><strong>Estimated Delivery:</strong> @s.EstimatedDeliveryUtc.Value.ToString("g")</p>
                         }
                         @if (s.ActualDeliveryUtc.HasValue)
                         {
                             <p class="text-success"><strong>Delivered:</strong> @s.ActualDeliveryUtc.Value.ToString("g")</p>
                         }
                     </div>
                 </div>
             </div>
         }
     </div>
 }

 @code {
     private List<ShipmentDto> shipments = [];
     private bool loading = true;

     protected override async Task OnInitializedAsync()
     {
         await LoadShipments();
     }

     private async Task LoadShipments()
     {
         loading = true;
         try
         {
             var authState = await AuthStateProvider.GetAuthenticationStateAsync();
             var email = authState.User.Identity?.Name ?? string.Empty;
             shipments = await ShipmentService.GetShipmentsForCustomerAsync(email);
         }
         catch
         {
             shipments = [];
         }
         loading = false;
     }

     private static string GetStatusBadgeClass(string status) => status switch
     {
         ShipmentStatuses.Delivered => "bg-success",
         ShipmentStatuses.Cancelled => "bg-danger",
         ShipmentStatuses.InTransit or ShipmentStatuses.OutForDelivery => "bg-info text-dark",
         _ => "bg-warning text-dark"
     };
 }

